# --- phase flips are not corrected by the bit-flip code, but the Hadamard-conjugate code fixes them
def logical_error_rate_Z(code, p, decoder):
    total = 0.0
    for pattern in itertools.product((0, 1), repeat=code.n):
        prob = np.prod([p if b else 1 - p for b in pattern])
        err = "".join("Z" if b else "I" for b in pattern)
        corr = decoder[code.syndrome(code.vec(err))]
        residual = (code.vec(err) + code.vec(corr)) % 2
        if not code.in_stabilizer_group(residual):
            total += prob
    return total
