# --- both error types together (independent X and Z with probability p each): neither code is enough
def logical_error_rate_XZ(code, p, decoder, trials=40000, seed=1):
    rng = np.random.default_rng(seed)
    fails = 0
    for _ in range(trials):
        xs = rng.random(code.n) < p; zs = rng.random(code.n) < p
        err = "".join("IXZY"[int(x) + 2 * int(z)] for x, z in zip(xs, zs))
        syn = code.syndrome(code.vec(err))
        corr = decoder.get(syn)
        if corr is None:
            fails += 1; continue
        residual = (code.vec(err) + code.vec(corr)) % 2
        fails += not code.in_stabilizer_group(residual)
    return fails / trials
