print(f"independent X and Z errors at p = {p} (Monte Carlo, 40,000 trials, decoder over all single-qubit Paulis): bit-flip code {logical_error_rate_XZ(bitflip, p, dec_all_b):.4f}, phase-flip code {logical_error_rate_XZ(phaseflip, p, dec_all_p):.4f}, bare qubit (any error) {1 - (1 - p) ** 2:.4f}")
