import itertools, math
import numpy as np

class StabilizerCode:
    # a stabilizer code on n qubits given by generator strings over I, X, Y, Z and (for k = 1) logical X and Z operators
    def __init__(self, stabilizers, logical_x=None, logical_z=None):
        self.n = len(stabilizers[0])
        self.S = [self.vec(s) for s in stabilizers]
        self.LX = self.vec(logical_x) if logical_x else None
        self.LZ = self.vec(logical_z) if logical_z else None
    @staticmethod
    def vec(s):
        x = np.array([c in "XY" for c in s], dtype=np.uint8); z = np.array([c in "ZY" for c in s], dtype=np.uint8)
        return np.concatenate([x, z])
    def label(self, v):
        n = self.n
        return "".join("IXZY"[int(v[i]) + 2 * int(v[n + i])] for i in range(n))
    def commutes(self, a, b):                                                # symplectic product: Paulis commute iff it is 0
        n = self.n
        return int(a[:n] @ b[n:] + a[n:] @ b[:n]) % 2 == 0
    def syndrome(self, e):
        return tuple(0 if self.commutes(e, s) else 1 for s in self.S)
    def weight(self, v):
        n = self.n
        return int(np.count_nonzero(v[:n] | v[n:]))
    def in_stabilizer_group(self, v):
        # v (commuting with all generators) is in the group iff it commutes with both logical operators (k = 1)
        return self.commutes(v, self.LX) and self.commutes(v, self.LZ)
    def all_errors(self, max_weight, letters="XYZ"):
        n = self.n
        for w in range(max_weight + 1):
            for pos in itertools.combinations(range(n), w):
                for paulis in itertools.product(letters, repeat=w):
                    s = ["I"] * n
                    for p, c in zip(pos, paulis): s[p] = c
                    yield "".join(s)
    def build_decoder(self, max_weight, letters="XYZ"):
        table = {}
        for e in self.all_errors(max_weight, letters):                                # lowest-weight error first, so the first one stored per syndrome is minimal
            table.setdefault(self.syndrome(self.vec(e)), e)
        return table
    def distance(self, limit=6):
        for w in range(1, limit + 1):
            for e in self.all_errors(w):
                if self.weight(self.vec(e)) != w: continue
                v = self.vec(e)
                if all(self.commutes(v, s) for s in self.S) and not self.in_stabilizer_group(v):
                    return w, e
        return None, None
