# --- the size of the stabilizer group, and the logical operators as elements of the normalizer
def group_elements(code):
    elems = {tuple([0] * (2 * code.n))}
    for g in code.S:
        elems |= {tuple((np.array(e) + g) % 2) for e in elems}
    return elems
print("stabilizer group of the five-qubit code has", len(group_elements(five)), "elements (2^4), and its normalizer has", len(group_elements(five)) * 4, "(times 2^(2k)): the extra elements are the logical operators")

# --- Gottesman-Knill: Clifford circuits on stabilizer states are simulated efficiently; here a cross-check of Qiskit's tableau against the state vector for random circuits
