# --- the leading coefficient of the logical error rate: count the weight-2 fault patterns that fool the lookup decoder (exact enumeration, depolarizing noise)
def leading_coefficient(code, decoder):
    bad = 0
    for e in code.all_errors(2):
        if code.weight(code.vec(e)) != 2: continue
        corr = decoder.get(code.syndrome(code.vec(e)))
        residual = (code.vec(e) + code.vec(corr)) % 2
        bad += not code.in_stabilizer_group(residual)
    return bad
